/* ================= Bookkeeping Bootcamp: content =================
   Module 2 of the Foundation course, rebuilt as 12 short "learn, then do" steps plus a month-end capstone.
   One invented company runs through all of it: Cedar & Clay Studio LLC, a pottery studio that teaches classes and sells mugs.
   Every person, company, document and number here is made up for practice. The example sales tax rate (8%) is invented; real rates depend on the place.
   Exercise formats:
     ["eq",  event, [assets, liabilities, equity] each "+", "-" or "0", why]
     ["sort", account, "A"|"L"|"E"|"R"|"X", why]
     ["dc",  "Increase"|"Decrease", account, "D"|"C", why]
     ["mc",  prompt, [correct, wrong, wrong...], why, visual?]
     ["je",  event, visual|null, [["D"|"C", account, amount]...], [extra accounts to choose from], why]
     ["tap", prompt, [[account, debit, credit]...], index of the wrong line, why] */
let CAMPCO="Cedar & Clay Studio";
const cdoc=(n,s,r,foot)=>({k:"doc",n,s,r,foot});
let CAMP=[
{id:"eq",ic:"⚖️",t:"The equation that never breaks",goal:"Say what any business event does to assets, liabilities and equity.",
 slides:[
  {h:"What a bookkeeper does",b:["A business has money events all day: a sale, a bill, a paycheck, a loan payment.","Bookkeeping records each one, in order, sorted into named accounts.","From those records anyone can see four things: what the business owns, what it owes, what it earned and what it spent."],
   v:{k:"flow",r:["Something happens: a sale, a purchase, a payment","A document proves it: receipt, invoice, bill, bank line","You record it: which accounts, how much, what date","Reports come out: profit and loss, balance sheet"]}},
  {h:"Your client for this module",b:["Cedar & Clay Studio LLC opens on December 1. The owner is Mara Quinn.","It teaches pottery classes, sells handmade mugs, has one part-time helper and bought a kiln with a bank loan.","You are the bookkeeper. Every step uses this same studio, and at the end you close its first month."],
   ex:"The studio, the people and every number are invented for practice."},
  {h:"Assets = Liabilities + Equity",b:["Assets: what the business owns or is owed. Cash, inventory, equipment, money customers owe.","Liabilities: what it owes to others. Bills, credit cards, loans, taxes collected for the government.","Equity: what is left for the owner. Assets minus liabilities.","The two sides are equal after every single entry. If they are not, something was recorded wrong."],
   v:{k:"calc",r:[["Assets","$18,400"],["Liabilities","− $6,900"],["Equity","$11,500",1],["Check: liabilities + equity","$18,400"]]}},
  {h:"Every event moves at least two things",v:{k:"cmp",a:["Both sides move",["Owner puts in $10,000: assets up, equity up","Bank lends $6,000: assets up, liabilities up","Rent of $1,500 is paid: assets down, equity down"]],b:["One side swaps inside itself",["A $7,200 kiln is bought with cash: one asset up, another down","A customer pays an invoice: cash up, money owed down","Total assets do not change"]]},
   ex:"That is why the method is called double-entry: each event is recorded in at least two places."},
  {h:"Where income and expenses fit",b:["Revenue (income) makes equity go up: the business earned something for its owner.","Expenses make equity go down: something was used up to run the business.","Owner draws also make equity go down, but they are not expenses. The owner simply took money out.","Borrowed money and money the owner puts in are never revenue."]}],
 ex:[
  ["eq","Mara puts $10,000 of her own savings into the studio's bank account.",["+","0","+"],"Cash (an asset) goes up. It came from the owner, so equity goes up. It is not income."],
  ["eq","The bank lends the studio $6,000 and deposits it in the studio's account.",["+","+","0"],"Cash goes up and so does a liability, the loan. Borrowed money is not income, so equity does not move."],
  ["eq","The studio buys a $7,200 kiln and pays for it from the bank account.",["0","0","0"],"One asset (equipment) goes up and another (cash) goes down by the same amount. Total assets do not change."],
  ["eq","The studio buys $300 of clay on its credit card and uses it all this month.",["0","+","-"],"The card balance is a liability, so liabilities go up. The clay was used up: an expense, which lowers equity."],
  ["eq","Mara teaches a class and the customer pays $500 on the spot.",["+","0","+"],"Cash goes up. The studio earned it, so equity goes up through revenue."],
  ["eq","The studio finishes a workshop and sends a $2,400 invoice. The customer has not paid yet.",["+","0","+"],"The money owed is an asset called accounts receivable. The work is done, so the revenue is earned now."],
  ["eq","The customer pays that $2,400 invoice.",["0","0","0"],"Cash goes up and accounts receivable goes down. The revenue was already counted when the invoice was sent."],
  ["eq","The studio pays $1,500 rent for the month.",["-","0","-"],"Cash goes down. Rent is an expense, which lowers equity."],
  ["eq","A supplier delivers $1,200 of mugs to resell and sends a bill due in 30 days.",["+","+","0"],"Inventory (an asset) goes up and accounts payable (a liability) goes up. Nothing is an expense until a mug is sold."],
  ["eq","The studio pays $700 of the supplier's bill.",["-","-","0"],"Cash goes down and the amount owed goes down. No new expense."],
  ["eq","Mara takes $800 out of the business account for herself.",["-","0","-"],"Cash goes down and equity goes down. It is an owner draw, not an expense and not wages."],
  ["eq","A customer pays $900 now for classes that will be taught in January.",["+","+","0"],"Cash goes up, but the studio still owes the classes. That is a liability called unearned revenue. No income yet."],
  ["eq","The studio repays $220 of the loan itself (principal only).",["-","-","0"],"Cash goes down and the loan goes down. Repaying what was borrowed is not an expense."]]},

{id:"acct",ic:"🗂️",t:"Five kinds of accounts",goal:"Put any account in the right group and on the right statement.",
 slides:[
  {h:"The chart of accounts",b:["An account is a labeled bucket for one kind of thing: Checking, Rent expense, Loan payable.","The chart of accounts is the list of every bucket the business uses.","Every account belongs to one of five types. The type decides which report it shows on and which side makes it grow."],
   v:{k:"cmp",a:["Balance sheet accounts",["Assets: owned or owed to the business","Liabilities: owed by the business","Equity: the owner's share"]],b:["Income statement accounts",["Revenue: earned from customers","Expenses: used up to run the business"]]}},
  {h:"How the list is usually numbered",v:{k:"tiers",r:[["1000s · Assets","Checking, receivables, inventory, equipment",30],["2000s · Liabilities","Payables, cards, taxes owed, loans",45],["3000s · Equity","Owner's capital, owner's draw",60],["4000s · Revenue","Class revenue, product sales",75],["5000s to 6000s · Expenses","Cost of goods sold, then rent, wages, supplies",100]]},
   ex:"Software such as QuickBooks sets up a starter chart for you. Your job is to keep it short and clear."},
  {h:"Cedar & Clay's chart",v:{k:"cmp",a:["Owns and owes",["Checking · Accounts receivable · Inventory","Prepaid insurance · Equipment","Accounts payable · Credit card payable","Sales tax payable · Payroll taxes payable","Unearned revenue · Loan payable"]],b:["Owner, income, costs",["Owner's capital · Owner's draw","Class revenue · Product sales","Cost of goods sold · Rent · Wages","Supplies · Advertising · Insurance","Depreciation · Interest · Bank fees"]]}},
  {h:"The ones people get wrong",b:["Prepaid insurance is an asset: the studio paid ahead and is still owed the coverage.","Unearned revenue is a liability: the studio was paid ahead and still owes the classes.","Sales tax collected is a liability: it belongs to the state, not to the studio.","Owner's draw is equity, not an expense.","Accumulated depreciation sits with the assets and reduces equipment. It is called a contra-asset."]},
  {h:"Permanent and temporary",b:["Balance sheet accounts carry their balance into the next year. The bank account does not reset on January 1.","Revenue and expense accounts start again at zero each year. The year's profit or loss moves into equity."]}],
 ex:[
  ["sort","Checking","A","Money in the bank is owned by the business."],
  ["sort","Accounts receivable","A","Money customers owe the studio. The studio owns the right to collect it."],
  ["sort","Inventory","A","Mugs waiting to be sold are owned by the studio."],
  ["sort","Prepaid insurance","A","Paid ahead: the studio is still owed the coverage, so it is an asset until the months pass."],
  ["sort","Equipment","A","The kiln and wheels are owned and last for years."],
  ["sort","Accounts payable","L","Bills from suppliers that are not paid yet."],
  ["sort","Credit card payable","L","The card balance is money owed to the card company."],
  ["sort","Sales tax payable","L","Collected from customers for the state. The studio owes it."],
  ["sort","Unearned revenue","L","Customers paid ahead. The studio owes them the classes."],
  ["sort","Loan payable","L","Money borrowed from the bank and still owed."],
  ["sort","Payroll taxes payable","L","Taxes held back from paychecks plus the employer's share, owed to the government."],
  ["sort","Owner's capital","E","What the owner has put in, plus profits left in the business."],
  ["sort","Owner's draw","E","Money the owner took out. It reduces equity. It is not an expense."],
  ["sort","Class revenue","R","Earned by teaching classes."],
  ["sort","Product sales","R","Earned by selling mugs."],
  ["sort","Rent expense","X","Used up to run the studio this month."],
  ["sort","Cost of goods sold","X","The cost of the mugs that were sold. An expense."],
  ["sort","Wages expense","X","The helper's gross pay."],
  ["sort","Interest expense","X","The cost of borrowing. Only the interest part of a loan payment is an expense."],
  ["mc","Which report shows Accounts receivable?",["The balance sheet","The income statement (profit and loss)","Neither: it is only a list of customers","Both reports"],"Receivables are an asset. Assets, liabilities and equity are on the balance sheet."],
  ["mc","Which accounts start again at zero every year?",["Revenue and expense accounts","Asset accounts","Liability accounts","All accounts"],"Revenue and expenses measure one period. Their result moves into equity and they restart."],
  ["mc","In a standard chart, account number 6100 is most likely",["an expense","an asset","a liability","revenue"],"Assets are in the 1000s, liabilities 2000s, equity 3000s, revenue 4000s, costs and expenses 5000s and up."]]},

{id:"dc",ic:"↔️",t:"Debits and credits",goal:"Know in one second which side makes an account grow.",
 slides:[
  {h:"Left and right, nothing more",b:["Debit means the left side of an account. Credit means the right side.","Neither word means good or bad, more or less.","Whether a debit makes an account bigger depends on the account's type."]},
  {h:"The one table to memorize",v:{k:"cmp",a:["Grow with a DEBIT",["Assets","Expenses","Owner's draw"]],b:["Grow with a CREDIT",["Liabilities","Equity (owner's capital)","Revenue"]]},
   ex:"The opposite side makes each one smaller. Cash is an asset: a debit adds to it and a credit takes from it."},
  {h:"Why it works",b:["Assets are on the left of the equation, so they grow on the left.","Liabilities and equity are on the right, so they grow on the right.","Revenue raises equity, so it grows on the right too.","Expenses and draws lower equity, so they grow on the left."],
   v:{k:"calc",r:[["Assets","= Liabilities + Equity"],["grow with debits","grow with credits",1]]}},
  {h:"The normal balance",b:["The side that makes an account grow is its normal balance.","Checking normally has a debit balance. Accounts payable normally has a credit balance.","A balance on the wrong side is a warning. Checking with a credit balance means the account is overdrawn or an entry is wrong."]},
  {h:"T-accounts",b:["A T-account is a quick sketch of one account: debits on the left, credits on the right.","Add each side. The balance is the bigger side minus the smaller side."],
   v:{k:"tacc",n:"Checking",l:["10,000 owner","6,000 loan","900 customer"],r:["7,200 kiln","1,500 rent"],bal:"Debit balance: 16,900 − 8,700 = 8,200"}},
  {h:"Why the bank says the opposite",b:["Your bank statement is written from the bank's side.","To the bank, your deposit is money it owes you: a liability, which grows with a credit.","So the bank 'credits' your account when money comes in. In your own books the same deposit is a debit to Checking."]}],
 ex:[
  ["dc","Increase","Checking","D","Checking is an asset. Assets grow with a debit."],
  ["dc","Decrease","Checking","C","An asset gets smaller with a credit. Every payment out of the bank credits Checking."],
  ["dc","Increase","Accounts receivable","D","Receivables are an asset: a debit adds to what customers owe."],
  ["dc","Decrease","Accounts receivable","C","When the customer pays, the asset shrinks with a credit."],
  ["dc","Increase","Inventory","D","Inventory is an asset."],
  ["dc","Increase","Accounts payable","C","Payables are a liability. Liabilities grow with a credit."],
  ["dc","Decrease","Accounts payable","D","Paying a bill makes the liability smaller: a debit."],
  ["dc","Increase","Loan payable","C","A loan is a liability. Borrowing credits it."],
  ["dc","Decrease","Loan payable","D","Repaying principal debits the loan."],
  ["dc","Increase","Owner's capital","C","Equity grows with a credit."],
  ["dc","Increase","Owner's draw","D","Draws reduce equity, so they grow on the debit side."],
  ["dc","Increase","Class revenue","C","Revenue raises equity, so it grows with a credit."],
  ["dc","Increase","Rent expense","D","Expenses lower equity, so they grow with a debit."],
  ["dc","Increase","Sales tax payable","C","Tax collected for the state is a liability."],
  ["dc","Increase","Unearned revenue","C","Money received before the work is done is a liability."],
  ["dc","Increase","Equipment","D","Equipment is an asset."],
  ["dc","Increase","Wages expense","D","An expense grows with a debit."],
  ["dc","Decrease","Prepaid insurance","C","Prepaid insurance is an asset. Using up a month of it credits the asset."],
  ["mc","What is the normal balance of Accounts payable?",["Credit","Debit","Zero","It has no normal balance"],"It is a liability, and liabilities grow with credits."],
  ["mc","Checking has debits of 4,000 and 900 and credits of 350. What is the balance?",["$4,550 debit","$5,250 debit","$4,550 credit","$3,650 debit"],"Debits total 4,900. Credits total 350. 4,900 − 350 = 4,550 on the debit side."],
  ["mc","An entry has debits of $500 and credits of $450. What happens?",["It cannot be posted until the two sides are equal","It posts, and the $50 goes to profit","It posts, and the bank balance absorbs the $50","The software ignores the smaller side"],"Debits must equal credits in every entry. Find the missing $50 before saving."],
  ["mc","The bank statement says the bank 'credited' your account $900. In the studio's books that is",["a debit to Checking","a credit to Checking","a credit to Class revenue only","not recorded"],"The statement is written from the bank's side. Money in is a debit to your own Checking account."]]},

{id:"je1",ic:"✍️",t:"Your first journal entries",goal:"Turn a plain event into a balanced entry.",
 slides:[
  {h:"What a journal entry holds",b:["A date.","The accounts, with debits listed first and credits after, slightly indented.","Amounts: total debits equal total credits.","A short memo saying what happened and which document proves it."],
   v:{k:"je",r:[["Checking","10,000",""],["Owner's capital","","10,000"]],n:"Dec 1. Owner put personal savings into the business. Deposit slip 001."}},
  {h:"Three questions for every event",v:{k:"flow",r:["1. Which accounts are touched? There are at least two.","2. What type is each, and did it go up or down?","3. Up or down on that type: is that a debit or a credit?","Check: do the debits equal the credits?"]},
   ex:"Rent paid by check: Rent expense went up (expense up = debit). Checking went down (asset down = credit)."},
  {h:"Start from the document",b:["Every entry rests on a document: a receipt, an invoice you sent, a bill you received, a bank or card statement line.","No document, no entry. Ask the owner for it.","Keep the document. Attach it in the software or file it by month."]},
  {h:"Money that looks like income but is not",b:["Owner puts money in: credit Owner's capital.","A loan arrives: credit Loan payable.","A customer pays ahead: credit Unearned revenue.","Recording any of these as revenue overstates profit, and the owner would pay tax on money that was never earned."]},
  {h:"Money out that is not an expense",b:["Buying equipment: debit Equipment, an asset.","Owner takes money for herself: debit Owner's draw.","Paying down a loan or a credit card: debit the liability.","Recording any of these as an expense understates profit."]}],
 ex:[
  ["je","Dec 1. Mara deposits $5,000 of her own savings into the studio's checking account.",cdoc("FIRST BANK · DEPOSIT RECEIPT","Cedar & Clay Studio LLC · Checking",[["From: Mara Quinn, personal savings",""],["Deposit","5,000.00",1]]),[["D","Checking","5,000.00"],["C","Owner's capital","5,000.00"]],["Class revenue","Loan payable","Owner's draw"],"Cash went up (asset, debit). The owner put it in, so equity went up (credit). It is not revenue."],
  ["je","Dec 1. The bank's $6,000 equipment loan is deposited in the studio's checking account.",cdoc("FIRST BANK · LOAN ADVICE","Loan 30-114 · Cedar & Clay Studio LLC",[["Loan proceeds deposited","6,000.00",1]],"First payment due Dec 30."),[["D","Checking","6,000.00"],["C","Loan payable","6,000.00"]],["Class revenue","Owner's capital","Interest expense"],"Cash went up and a liability went up. Borrowed money is never revenue."],
  ["je","Dec 2. The studio buys a pottery wheel for $900 with its debit card.",cdoc("POTTER'S SUPPLY (practice) · RECEIPT","Dec 2",[["Electric pottery wheel","900.00"],["Paid by debit card","900.00",1]]),[["D","Equipment","900.00"],["C","Checking","900.00"]],["Supplies expense","Accounts payable","Credit card payable"],"The wheel will last for years: an asset. A debit card takes the money straight from Checking."],
  ["je","Dec 3. The studio pays December rent of $1,500 by check.",cdoc("CHECK 1001","Pay to: Harbor Property Co. (practice)",[["December rent","1,500.00",1]]),[["D","Rent expense","1,500.00"],["C","Checking","1,500.00"]],["Prepaid insurance","Accounts payable","Owner's draw"],"Rent for this month is used up this month: an expense (debit). Checking went down (credit)."],
  ["je","Dec 6. The electricity bill of $140 arrives and is paid from checking the same day.",cdoc("CITY POWER (practice) · BILL","Service to Dec 5",[["Amount due","140.00",1]],"Paid online Dec 6."),[["D","Utilities expense","140.00"],["C","Checking","140.00"]],["Accounts payable","Rent expense","Supplies expense"],"Paid right away, so no payable is needed. Expense up, cash down."],
  ["je","Dec 7. Mara teaches a class. The student pays $300 in cash, deposited the same day.",cdoc("CEDAR & CLAY · SALES RECEIPT 101","Dec 7",[["Wheel-throwing class","300.00"],["Paid in cash","300.00",1]]),[["D","Checking","300.00"],["C","Class revenue","300.00"]],["Unearned revenue","Accounts receivable","Owner's capital"],"The class was taught and paid for today. Cash up (debit), revenue up (credit)."],
  ["je","Dec 8. The studio buys $85 of glaze on the business credit card. It will be used this month.",cdoc("GLAZE WORKS (practice) · RECEIPT","Dec 8",[["Glaze, 4 jars","85.00"],["Charged to card ending 2210","85.00",1]]),[["D","Supplies expense","85.00"],["C","Credit card payable","85.00"]],["Checking","Accounts payable","Equipment"],"Nothing left the bank yet. The studio now owes the card company: a liability goes up with a credit."],
  ["je","Dec 9. Mara uses the business debit card for $400 of personal groceries.",cdoc("FRESH MARKET (practice) · RECEIPT","Dec 9",[["Groceries","400.00"],["Paid by debit card","400.00",1]],"Owner's note: personal."),[["D","Owner's draw","400.00"],["C","Checking","400.00"]],["Wages expense","Supplies expense","Owner's capital"],"Personal spending from the business account is an owner draw. It is not a business expense and not wages."],
  ["tap","The studio paid $200 for an ad from checking. One line of this entry is on the wrong side. Tap it.",[["Advertising expense","200.00",""],["Checking","200.00",""]],1,"Paying from the bank makes Checking smaller, and an asset gets smaller with a credit. As written, the entry has $400 of debits and no credits."],
  ["mc","A $6,000 bank loan is deposited. Why is it not recorded as revenue?",["It must be paid back, so it is a liability","Loans are recorded only when they are repaid","Revenue can only be cash","It is revenue, but it is taxed later"],"Revenue is earned from customers. A loan creates a debt of the same size, so equity does not change."],
  ["mc","You find a $450 payment on the bank statement with no receipt and no memo. What do you do first?",["Ask the owner what it was and get the document","Record it as Supplies expense, the most common one","Record it as Owner's draw","Leave it out so the books stay clean"],"No document, no entry. Guessing the account is how books go wrong."]]},

{id:"sales",ic:"🧾",t:"Money in: sales, invoices and deposits",goal:"Record cash sales, invoices, customer payments, sales tax and prepayments.",
 slides:[
  {h:"Two ways a sale happens",v:{k:"cmp",a:["Paid now",["Customer pays at the time of sale","Document: sales receipt","Debit Checking, credit revenue"]],b:["Paid later",["You send an invoice with terms, such as net 15","Debit Accounts receivable, credit revenue","When paid: debit Checking, credit Accounts receivable"]]},
   ex:"The revenue is recorded once, when the invoice is made. The payment only swaps one asset for another."},
  {h:"Accounts receivable",b:["Accounts receivable (A/R) is the total customers owe on open invoices.","An aging report lists each open invoice by how late it is: current, 1 to 30 days, 31 to 60 and so on.","The most common mistake: recording the payment as new revenue. The sale is then counted twice and the invoice still shows as unpaid."]},
  {h:"Sales tax is not the studio's money",b:["When the studio sells a mug it collects sales tax for the state.","The tax goes to Sales tax payable, a liability, not to revenue.","When the tax is sent to the state: debit Sales tax payable, credit Checking."],
   v:{k:"je",r:[["Checking","216.00",""],["Product sales","","200.00"],["Sales tax payable","","16.00"]],n:"Mugs sold for $200 plus 8% tax (an invented rate for practice)."}},
  {h:"Paid before the work is done",b:["A gift certificate or a deposit for future classes is not income yet.","Credit Unearned revenue, a liability, when the money arrives.","When the class is taught, move that part to revenue: debit Unearned revenue, credit Class revenue."]},
  {h:"Card sales and fees",b:["The card processor deposits the sale minus its fee, usually a day or two later.","Record the full sale as revenue and the fee as an expense. Do not record only the net deposit."],
   v:{k:"je",r:[["Checking","485.50",""],["Merchant fees","14.50",""],["Class revenue","","500.00"]],n:"A $500 class paid by card. The processor kept $14.50."}}],
 ex:[
  ["je","Dec 10. Ten mugs are sold for $200 plus $16 sales tax. The customer pays $216 in cash.",cdoc("CEDAR & CLAY · SALES RECEIPT 104","Dec 10",[["10 mugs at $20.00","200.00"],["Sales tax 8%","16.00"],["Paid in cash","216.00",1]]),[["D","Checking","216.00"],["C","Product sales","200.00"],["C","Sales tax payable","16.00"]],["Class revenue","Accounts receivable","Sales tax expense"],"The studio keeps $200. The $16 belongs to the state until it is sent in."],
  ["je","Dec 10. The studio teaches a team workshop for Birch & Co. and sends an invoice for $2,400, due in 15 days.",cdoc("CEDAR & CLAY · INVOICE 1001","Bill to: Birch & Co. (practice) · Dec 10 · Net 15",[["Team workshop, 12 people","2,400.00"],["Amount due","2,400.00",1]]),[["D","Accounts receivable","2,400.00"],["C","Class revenue","2,400.00"]],["Checking","Unearned revenue","Accounts payable"],"The work is done, so the revenue is earned now. No cash yet: the customer owes it."],
  ["je","Dec 20. Birch & Co. pays $1,000 toward invoice 1001.",cdoc("FIRST BANK · DEPOSIT","Dec 20",[["Check from Birch & Co., invoice 1001","1,000.00",1]]),[["D","Checking","1,000.00"],["C","Accounts receivable","1,000.00"]],["Class revenue","Unearned revenue","Product sales"],"The revenue was recorded on Dec 10. This payment only reduces what the customer owes. $1,400 is still open."],
  ["je","Dec 12. A customer buys a $300 gift certificate for classes to be taken next month.",cdoc("CEDAR & CLAY · GIFT CERTIFICATE 07","Dec 12",[["Good for classes in January","300.00"],["Paid by debit card","300.00",1]]),[["D","Checking","300.00"],["C","Unearned revenue","300.00"]],["Class revenue","Accounts receivable","Owner's capital"],"The studio has the cash but still owes the classes. That is a liability until they are taught."],
  ["je","Jan 9. The gift certificate holder takes $100 of classes.",null,[["D","Unearned revenue","100.00"],["C","Class revenue","100.00"]],["Checking","Accounts receivable","Product sales"],"No new cash. $100 of what was owed has now been earned, so it moves from the liability to revenue."],
  ["je","Dec 14. A $500 class is paid by card. The processor deposits $485.50 and keeps a $14.50 fee.",cdoc("CARD PROCESSOR (practice) · PAYOUT","Dec 14",[["Gross sales","500.00"],["Processing fee","−14.50"],["Deposited to checking","485.50",1]]),[["D","Checking","485.50"],["D","Merchant fees","14.50"],["C","Class revenue","500.00"]],["Bank fees","Accounts receivable","Sales tax payable"],"Revenue is the full $500. The fee is a separate expense. Recording only $485.50 would hide both."],
  ["je","Jan 20. The studio sends the state the $96 of sales tax it collected.",null,[["D","Sales tax payable","96.00"],["C","Checking","96.00"]],["Sales tax expense","Product sales","Accounts payable"],"Paying the tax clears the liability. It was never revenue, so it is not an expense either."],
  ["je","Dec 16. A customer returns a chipped mug and gets $20 back in cash. (Ignore sales tax here.)",null,[["D","Sales returns","20.00"],["C","Checking","20.00"]],["Product sales","Cost of goods sold","Accounts receivable"],"A refund reduces sales. Many charts use a Sales returns account so the owner can see how much comes back."],
  ["mc","A $2,400 workshop is taught and invoiced on Dec 10. The customer pays part on Dec 20. On accrual books, when is it income?",["Dec 10, when the work is done and invoiced","Dec 20, when the first payment arrives","When the invoice is paid in full","Jan 1, the start of the next period"],"Accrual means income is recorded when it is earned, whether or not cash has arrived."],
  ["mc","What does an A/R aging report show?",["Each unpaid customer invoice and how late it is","Every bill the studio owes","Sales by product","The bank balance by day"],"It is the tool for collecting money: who owes, how much, for how long."],
  ["mc","A customer pays an invoice and the payment is recorded as new Class revenue. What is wrong now?",["Revenue is counted twice and the invoice still shows as unpaid","Nothing: cash and revenue both went up","Revenue is too low","The bank balance is too low"],"The invoice already created the revenue. The payment should credit Accounts receivable."]]},

{id:"buy",ic:"💳",t:"Money out: bills, cards and owner draws",goal:"Record bills, bill payments, card charges and what is not an expense.",
 slides:[
  {h:"Pay now or pay later",v:{k:"cmp",a:["Paid now",["Check, debit card or cash","Debit the expense or asset","Credit Checking"]],b:["Paid later",["A bill from a supplier with terms","Debit the expense or asset, credit Accounts payable","When paid: debit Accounts payable, credit Checking"]]},
   ex:"The expense is recorded once, when the bill arrives. Paying the bill only clears the liability."},
  {h:"A credit card is a loan you top up daily",b:["Each charge: debit the expense, credit Credit card payable.","Paying the statement: debit Credit card payable, credit Checking.","The most common mistake: recording the statement payment as an expense. Every charge is then counted twice."]},
  {h:"Expense or asset?",b:["Used up within the year: an expense. Clay, rent, ads, repairs.","Lasts more than a year and costs real money: an asset. A kiln, a laptop, a vehicle.","Paid ahead for future months: a prepaid asset. Twelve months of insurance.","Small tools are usually just expensed. Businesses set a dollar line for this."]},
  {h:"Business and personal",b:["The business paid something personal: debit Owner's draw.","The owner paid a business cost with her own money and is not paid back: debit the expense, credit Owner's capital.","Mixing the two is the main reason small-business books are wrong at tax time. A separate business account and card fix most of it."]},
  {h:"Paying people who are not employees",b:["A photographer or repair person in business for themselves is a contractor.","Get a Form W-9 from each contractor before the first payment. It gives the name and tax number needed for year-end reporting.","Record the payment in its own account, such as Contract labor, so year-end forms are easy."]}],
 ex:[
  ["je","Dec 5. Kiln Supply Co. delivers $260 of clay with a bill due in 30 days. The clay will be used this month.",cdoc("KILN SUPPLY CO. (practice) · INVOICE 5521","Bill to: Cedar & Clay Studio · Dec 5 · Net 30",[["Stoneware clay, 10 bags","260.00"],["Amount due","260.00",1]]),[["D","Supplies expense","260.00"],["C","Accounts payable","260.00"]],["Checking","Credit card payable","Inventory"],"The expense is recorded when the bill arrives. Nothing has left the bank yet."],
  ["je","Dec 28. The studio pays that $260 bill by check.",cdoc("CHECK 1006","Pay to: Kiln Supply Co. · Invoice 5521",[["Amount","260.00",1]]),[["D","Accounts payable","260.00"],["C","Checking","260.00"]],["Supplies expense","Credit card payable","Owner's draw"],"The expense was already recorded on Dec 5. This only clears what was owed."],
  ["je","Dec 9. A $120 social media ad is charged to the business credit card.",cdoc("AD PLATFORM (practice) · RECEIPT","Dec 9",[["Holiday class promotion","120.00"],["Charged to card ending 2210","120.00",1]]),[["D","Advertising expense","120.00"],["C","Credit card payable","120.00"]],["Checking","Accounts payable","Supplies expense"],"A card charge raises what the studio owes the card company."],
  ["je","Jan 5. The studio pays the credit card statement of $420 from checking.",cdoc("BUSINESS CARD ending 2210 · STATEMENT","Closing date Dec 31",[["December purchases","420.00"],["Payment due","420.00",1]],"Paid from checking Jan 5."),[["D","Credit card payable","420.00"],["C","Checking","420.00"]],["Supplies expense","Advertising expense","Bank fees"],"Each charge was already an expense on the day it happened. The payment only reduces the card balance."],
  ["je","Dec 2. The studio pays $1,200 for twelve months of insurance, December through November.",cdoc("SHIELD MUTUAL (practice) · POLICY RECEIPT","Policy period Dec 1 to Nov 30",[["Annual premium","1,200.00",1]],"Paid by check 1000."),[["D","Prepaid insurance","1,200.00"],["C","Checking","1,200.00"]],["Insurance expense","Accounts payable","Equipment"],"Eleven of the twelve months are still ahead. It is an asset now and becomes expense one month at a time."],
  ["je","Dec 11. Mara pays her personal phone bill of $90 with the business debit card.",null,[["D","Owner's draw","90.00"],["C","Checking","90.00"]],["Utilities expense","Wages expense","Owner's capital"],"A personal cost paid by the business is a draw, not a business expense."],
  ["je","Dec 13. Mara buys $75 of studio sponges with her personal card and will not be paid back.",null,[["D","Supplies expense","75.00"],["C","Owner's capital","75.00"]],["Checking","Owner's draw","Credit card payable"],"It is a real business expense. The owner paid for it herself, which is the same as putting $75 into the business."],
  ["je","Dec 17. The studio pays a freelance photographer $350 by check for product photos.",cdoc("CHECK 1004","Pay to: Lena Ortiz Photography (practice)",[["Product photos","350.00",1]]),[["D","Contract labor","350.00"],["C","Checking","350.00"]],["Wages expense","Owner's draw","Payroll taxes payable"],"She runs her own business, so this is not wages and nothing is withheld."],
  ["tap","The $420 card payment was recorded like this. Tap the line that is wrong.",[["Supplies expense","420.00",""],["Checking","","420.00"]],0,"The debit should be Credit card payable. The purchases were already expensed when they were charged, so this counts them twice."],
  ["mc","What should the studio get from the photographer before paying her?",["A completed Form W-9","A Form W-4","A Form I-9","Nothing: the check is the record"],"Form W-9 gives a contractor's name and tax number. W-4 and I-9 are for employees."],
  ["mc","The studio buys a $2,000 laptop it will use for four years. In the books it is",["equipment, an asset that is depreciated","office supplies expense","an owner draw","prepaid expense"],"It lasts more than a year and the cost is significant, so it goes on the balance sheet and is spread over its life."]]},

{id:"inv",ic:"📦",t:"Inventory and cost of goods sold",goal:"Follow a mug from purchase to sale and find the gross profit.",
 slides:[
  {h:"Goods for resale are an asset first",b:["Mugs bought to resell go to Inventory, an asset.","They are not an expense on the day they are bought.","When a mug is sold, its cost moves from Inventory to Cost of goods sold (COGS), an expense."]},
  {h:"Every product sale has two halves",v:{k:"je",r:[["Checking","200.00",""],["Product sales","","200.00"],["Cost of goods sold","80.00",""],["Inventory","","80.00"]],n:"Ten mugs sold at $20 each. They cost $8 each."},
   ex:"The first pair records what the customer paid. The second pair records what the studio gave up. Software makes the second pair for you when products are set up with a cost."},
  {h:"Gross profit",v:{k:"calc",r:[["Product sales","$200"],["Cost of goods sold","− $80"],["Gross profit","$120",1],["Gross margin: 120 ÷ 200","60%"]]},
   ex:"Gross profit is what is left to pay rent, wages and everything else."},
  {h:"What goes into the cost",b:["The price paid to the supplier.","Shipping paid to get the goods to the studio (freight-in).","Not included: the cost of sending goods out to customers, or the rent of the shop. Those are regular expenses."]},
  {h:"Counting and the yearly formula",b:["Count the shelf at least once a year and compare it with the books.","Broken, lost or stolen items are removed from Inventory and added to cost.","Without item-by-item tracking, use the formula below."],
   v:{k:"calc",r:[["Beginning inventory","$800"],["Plus purchases","+ $1,200"],["Less ending inventory (the count)","− $700"],["Cost of goods sold","$1,300",1]]}}],
 ex:[
  ["je","Dec 5. Hillside Pottery delivers 150 mugs at $8 each with a $1,200 bill due in 30 days.",cdoc("HILLSIDE POTTERY (practice) · INVOICE 318","Bill to: Cedar & Clay Studio · Dec 5 · Net 30",[["150 mugs at $8.00","1,200.00"],["Amount due","1,200.00",1]]),[["D","Inventory","1,200.00"],["C","Accounts payable","1,200.00"]],["Cost of goods sold","Supplies expense","Checking"],"Goods for resale are an asset until they are sold."],
  ["je","Dec 12. Ten mugs are sold for $200 cash. Record what the customer paid. (Ignore sales tax here.)",null,[["D","Checking","200.00"],["C","Product sales","200.00"]],["Inventory","Cost of goods sold","Accounts receivable"],"This is the selling-price half of the sale."],
  ["je","Ten mugs that cost $8 each were just sold. Record the cost half of the sale.",null,[["D","Cost of goods sold","80.00"],["C","Inventory","80.00"]],["Product sales","Checking","Supplies expense"],"The cost of what was sold becomes an expense, and the asset on the shelf shrinks."],
  ["mc","Ten mugs sold for $200. They cost $80. What is the gross profit?",["$120","$200","$80","$280"],"Sales $200 minus cost $80."],
  ["mc","Sales $200, gross profit $120. What is the gross margin?",["60%","40%","80%","120%"],"Gross profit ÷ sales = 120 ÷ 200."],
  ["mc","Beginning inventory $800, purchases $1,200, ending count $700. What is cost of goods sold?",["$1,300","$2,000","$700","$1,900"],"800 + 1,200 − 700 = 1,300."],
  ["je","Dec 31. The count shows three mugs broke in storage. They cost $24 in total.",null,[["D","Cost of goods sold","24.00"],["C","Inventory","24.00"]],["Product sales","Owner's draw","Checking"],"Broken goods can no longer be sold, so their cost leaves Inventory. Some charts use a separate Inventory shrinkage account."],
  ["mc","Mugs bought in December and still on the shelf on Dec 31 appear",["on the balance sheet, as inventory","on the income statement, as cost of goods sold","on the income statement, as supplies","nowhere until they are sold"],"Unsold goods are still an asset."],
  ["mc","All $1,200 of mugs was recorded as an expense on the day it was bought. Only a third were sold. This month's profit is",["too low","too high","correct","unaffected"],"Only the cost of the mugs sold is an expense. Expensing all of it understates profit and leaves inventory off the balance sheet."],
  ["mc","The studio paid $45 shipping to receive the mugs from the supplier. That $45 is",["part of the cost of the inventory","advertising expense","an owner draw","sales tax"],"Freight-in is part of what it cost to get the goods ready to sell."]]},

{id:"pay",ic:"💵",t:"Payroll in the books",goal:"Record a payday and the tax deposit that follows.",
 slides:[
  {h:"One paycheck, several owners",v:{k:"calc",r:[["Gross pay: 50 hours at $20","$1,000.00"],["Federal income tax withheld","− $80.00"],["Social Security 6.2%","− $62.00"],["Medicare 1.45%","− $14.50"],["Net pay to the helper","$843.50",1]]},
   ex:"The income tax figure comes from the worker's Form W-4 and the IRS tables. Here it is given."},
  {h:"What the employer adds",b:["The employer pays its own Social Security (6.2%) and Medicare (1.45%) on the same wages: $76.50 here.","Employers also pay federal and state unemployment tax. Nothing for those is taken from the worker's pay.","So $1,000 of wages costs the studio more than $1,000."]},
  {h:"The payday entry",v:{k:"je",r:[["Wages expense","1,000.00",""],["Payroll tax expense","76.50",""],["Checking","","843.50"],["Payroll taxes payable","","233.00"]],n:"Payable: 80.00 + 62.00 + 14.50 withheld, plus 76.50 employer share."},
   ex:"Wages expense is always the gross amount, not the net check."},
  {h:"Held in trust",b:["Money withheld from a paycheck never belonged to the business. It is held for the government.","It sits in Payroll taxes payable until it is deposited.","When deposited: debit Payroll taxes payable, credit Checking. No new expense.","Using that money for anything else is one of the most serious mistakes an employer can make."]},
  {h:"Employee or contractor",v:{k:"cmp",a:["Employee",["Business controls how and when the work is done","Taxes are withheld from each check","Year-end form: W-2"]],b:["Independent contractor",["Runs their own business","Nothing withheld; they pay their own tax","Year-end form: 1099-NEC"]]}}],
 ex:[
  ["mc","Gross pay $1,000. Withheld: income tax $80, Social Security $62, Medicare $14.50. What is the net pay?",["$843.50","$923.50","$920.00","$767.00"],"1,000 − 80 − 62 − 14.50 = 843.50."],
  ["mc","What is 6.2% Social Security tax on $1,000 of wages?",["$62.00","$6.20","$14.50","$76.50"],"1,000 × 0.062 = 62."],
  ["mc","Gross wages are $1,000 and the employer's own taxes are $76.50. What does this payday cost the studio?",["$1,076.50","$1,000.00","$843.50","$920.00"],"Gross wages 1,000 plus the employer's Social Security and Medicare 76.50."],
  ["je","Dec 24. Payday. Gross $1,000.00, net check $843.50, employer share of taxes $76.50.",cdoc("PAYROLL REGISTER · Dec 24","Helper: Jo Tran (practice)",[["Gross pay","1,000.00"],["Federal income tax","−80.00"],["Social Security","−62.00"],["Medicare","−14.50"],["Net pay (check 1005)","843.50",1],["Employer Social Security and Medicare","76.50"]]),[["D","Wages expense","1,000.00"],["D","Payroll tax expense","76.50"],["C","Checking","843.50"],["C","Payroll taxes payable","233.00"]],["Owner's draw","Contract labor","Accounts payable"],"Expense: gross wages plus the employer's taxes. Cash out: the net check. Everything else is owed to the government."],
  ["je","Jan 15. The studio deposits the $233.00 of payroll taxes with the IRS.",null,[["D","Payroll taxes payable","233.00"],["C","Checking","233.00"]],["Payroll tax expense","Wages expense","Bank fees"],"The expense was recorded on payday. The deposit only clears the liability."],
  ["mc","Who does the money withheld from a paycheck belong to?",["The government; the employer holds it until deposit","The employer, until year end","The employee, who gets it back each quarter","The bank"],"That is why it is recorded as a liability and never as income."],
  ["mc","Which of these is NOT taken out of an employee's pay?",["Federal unemployment tax (FUTA)","Federal income tax","Social Security tax","Medicare tax"],"FUTA is paid only by the employer."],
  ["tap","One line of this payday entry is on the wrong side. Tap it.",[["Wages expense","1,000.00",""],["Payroll tax expense","76.50",""],["Payroll taxes payable","233.00",""],["Checking","","843.50"]],2,"The taxes owed are a liability, and a liability grows with a credit. As written, the debits (1,309.50) do not equal the credits (843.50)."],
  ["mc","The helper worked 25 hours at $20 an hour. What is the gross pay?",["$500","$420","$461.75","$538.25"],"Hours × rate = 25 × 20."],
  ["mc","The studio pays a contractor $350. How much tax does it withhold?",["None: a contractor handles their own taxes","7.65%","Federal income tax only","The same as for an employee"],"Withholding applies to employees. A contractor is paid the full amount and reports it themselves."]]},

{id:"fa",ic:"🏭",t:"Equipment, depreciation and loans",goal:"Record a big purchase, spread its cost and split a loan payment.",
 slides:[
  {h:"A kiln is not a December expense",b:["The kiln will fire pots for years. Charging all $7,200 to December would make December look terrible and later months too good.","So it is recorded as Equipment, an asset.","Its cost is moved to expense a little each month while it is used. That is depreciation."]},
  {h:"Straight-line depreciation",v:{k:"calc",r:[["Kiln cost","$7,200"],["Expected life","5 years = 60 months"],["Depreciation each month","$120",1]]},
   ex:"Tax returns use their own depreciation rules, often faster. The books and the tax return can differ, and that is normal."},
  {h:"The monthly entry",v:{k:"je",r:[["Depreciation expense","120.00",""],["Accumulated depreciation","","120.00"]],n:"Dec 31. One month of kiln depreciation."},
   ex:"Equipment itself stays at $7,200. Accumulated depreciation is a separate account that grows and is subtracted from it. Cost minus accumulated depreciation is the book value."},
  {h:"Buying with a loan",v:{k:"je",r:[["Equipment","7,200.00",""],["Checking","","1,200.00"],["Loan payable","","6,000.00"]],n:"A $7,200 kiln: $1,200 down and $6,000 financed."}},
  {h:"A loan payment has two parts",b:["Principal: paying back what was borrowed. It reduces the loan. It is not an expense.","Interest: the cost of borrowing. It is the only part that is an expense.","The lender's statement shows the split for every payment."],
   v:{k:"je",r:[["Loan payable","220.00",""],["Interest expense","30.00",""],["Checking","","250.00"]],n:"A $250 payment. Profit falls by $30 only."}}],
 ex:[
  ["je","Dec 2. The studio buys a $7,200 kiln: $1,200 from checking and $6,000 on a new loan from the seller's lender.",cdoc("KILN DEPOT (practice) · SALES CONTRACT","Dec 2",[["Electric kiln, model K-18","7,200.00"],["Down payment by check","1,200.00"],["Financed, 60 months","6,000.00",1]]),[["D","Equipment","7,200.00"],["C","Checking","1,200.00"],["C","Loan payable","6,000.00"]],["Supplies expense","Accounts payable","Owner's capital"],"The whole cost is the asset. It was paid for partly with cash and partly with debt."],
  ["mc","The kiln cost $7,200 and should last 5 years. What is straight-line depreciation per month?",["$120","$1,440","$144","$600"],"7,200 ÷ 60 months = 120."],
  ["je","Dec 31. Record one month of kiln depreciation, $120.",null,[["D","Depreciation expense","120.00"],["C","Accumulated depreciation","120.00"]],["Equipment","Checking","Loan payable"],"The credit goes to Accumulated depreciation, not to Equipment, so the original cost stays visible."],
  ["mc","After 10 months, what is the kiln's book value?",["$6,000","$7,200","$1,200","$7,080"],"Cost 7,200 minus accumulated depreciation of 10 × 120 = 1,200."],
  ["je","Dec 30. The $250 loan payment leaves checking: $220 is principal and $30 is interest.",cdoc("FIRST BANK · LOAN 30-114 · PAYMENT","Dec 30",[["Principal","220.00"],["Interest","30.00"],["Total payment","250.00",1],["Balance after payment","5,780.00"]]),[["D","Loan payable","220.00"],["D","Interest expense","30.00"],["C","Checking","250.00"]],["Bank fees","Equipment","Owner's draw"],"Principal reduces the debt. Only the interest is an expense."],
  ["mc","A $250 loan payment is $220 principal and $30 interest. How much does it reduce this month's profit?",["$30","$250","$220","$0"],"Only interest is an expense."],
  ["mc","A $6,000 loan gets a $250 payment: $220 principal, $30 interest. What is the loan balance now?",["$5,780","$5,750","$5,970","$6,000"],"Only the principal part reduces the loan: 6,000 − 220."],
  ["mc","Accumulated depreciation is",["a contra-asset: it has a credit balance and reduces equipment on the balance sheet","an expense on the income statement","a liability owed to the equipment seller","a cash reserve for buying the next kiln"],"It collects all depreciation taken so far. No cash is set aside by it."],
  ["mc","The whole $250 loan payment was recorded as Interest expense. What is the result?",["Profit is $220 too low and the loan still shows $6,000","Profit is $250 too high","Cash is wrong by $220","Nothing: the totals still balance, so it is fine"],"The entry balances, but it is in the wrong accounts. Balanced does not mean correct."],
  ["mc","The studio buys a $60 set of trimming tools that will last a few years. Most businesses would",["expense it right away, because the amount is small","depreciate it over five years","record it as inventory","record it as an owner draw"],"Tracking tiny assets is not worth the work. Businesses set a dollar line below which purchases are simply expensed."]]},

{id:"rec",ic:"🏦",t:"Bank reconciliation",goal:"Explain every dollar of difference between the bank and the books.",
 slides:[
  {h:"Why the two numbers differ",b:["The books and the bank statement almost never show the same balance on the same day.","Usually nobody made a mistake. The two just learned about things at different times.","Reconciling every month proves the books are complete and catches errors and theft early."]},
  {h:"Two lists",v:{k:"cmp",a:["The bank does not know yet",["Deposits in transit: made, not yet on the statement","Outstanding checks: written, not yet cleared","These adjust the BANK side. No entry in the books."]],b:["The books do not know yet",["Bank fees and interest","Automatic payments nobody recorded","Errors in the books","These need an ENTRY in the books."]]}},
  {h:"The worksheet",v:{k:"calc",r:[["Bank statement balance","$4,300"],["Add deposit in transit","+ $200"],["Less outstanding check","− $150"],["Adjusted bank balance","$4,350",1],["Book balance","$4,365"],["Less bank fee not yet recorded","− $15"],["Adjusted book balance","$4,350",1]]},
   ex:"When the two adjusted balances agree, the reconciliation is done."},
  {h:"How to do it",v:{k:"flow",r:["Start with last month's reconciled balance","Tick every statement line that matches a line in the books","Unticked on the statement: record it in the books","Unticked in the books: list it as outstanding or in transit","The difference must be zero"]}},
  {h:"When it will not balance",b:["A difference that divides by 9 often means two digits were swapped: 85 typed as 58 is off by 27.","A difference equal to one transaction: something is missing or entered twice.","Half the difference matches a transaction: it may be on the wrong side.","Never post a made-up entry to force the difference to zero. Find it."]}],
 ex:[
  ["mc","Books: $4,365. Bank statement: $4,300. A $200 deposit made on Dec 31 is not on the statement. What is it?",["A deposit in transit: add it to the bank side","An outstanding check: subtract it from the bank side","A bank error: call the bank","Missing revenue: record it in the books again"],"The books already have it. The bank will show it next month.",{k:"calc",r:[["Book balance, Checking","$4,365"],["Bank statement ending balance","$4,300"],["Dec 31 deposit, not on statement","$200"],["Check 1012, not cleared","$150"],["Bank service fee on statement","$15"]]}],
  ["mc","Check 1012 for $150 was written on Dec 29 and has not cleared the bank. What is it?",["An outstanding check: subtract it from the bank side","A deposit in transit: add it to the bank side","An expense to record again","An error in the books"],"The books already reduced cash. The bank will catch up when the payee deposits the check."],
  ["mc","The statement shows a $15 service fee that is not in the books. What do you do?",["Record it in the books: it reduces the book balance","Add it to the bank side","Ignore it: fees are the bank's business","Wait until next month"],"The bank already took the money. The books must record the expense."],
  ["mc","Statement $4,300, deposit in transit $200, outstanding check $150. What is the adjusted bank balance?",["$4,350","$4,650","$4,250","$3,950"],"4,300 + 200 − 150."],
  ["mc","Books $4,365, unrecorded bank fee $15. What is the adjusted book balance?",["$4,350","$4,380","$4,365","$4,335"],"4,365 − 15. It matches the adjusted bank balance, so the account is reconciled."],
  ["je","Record the $15 bank service fee in the books.",null,[["D","Bank fees","15.00"],["C","Checking","15.00"]],["Interest expense","Accounts payable","Owner's draw"],"An expense goes up and cash goes down."],
  ["je","The statement also shows $2 of interest earned that is not in the books. Record it.",null,[["D","Checking","2.00"],["C","Interest income","2.00"]],["Bank fees","Class revenue","Owner's capital"],"The bank added money, so Checking goes up. Interest earned is its own kind of income."],
  ["mc","After ticking everything, the difference is $27. What do you check first?",["Swapped digits, because 27 divides by 9","The owner's personal account","The sales tax rate","Whether the bank is wrong"],"A difference that divides evenly by 9 is the classic sign of a transposition, such as 85 entered as 58."],
  ["mc","A check was written and cleared for $450 but was recorded in the books as $540. What is the fix?",["Correct the entry in the books: Checking goes up by $90","Ask the bank to change the check to $540","List $90 as an outstanding check","Nothing: it will even out next month"],"The bank is right. The books took out $90 too much, so the entry is corrected."],
  ["mc","Everything is ticked and a $40 difference remains that you cannot find today. What do you do?",["Keep looking and do not finish the reconciliation with a forced entry","Post $40 to Bank fees so it balances","Post $40 to Owner's draw","Change last month's ending balance"],"A forced entry hides a real error or a real loss. An unexplained difference stays open until it is explained."],
  ["mc","A check written six months ago is still outstanding. What is the sensible next step?",["Contact the payee; it may need to be voided and reissued","Delete it from the books without telling anyone","Record it as income","Leave it on the list forever"],"Old outstanding checks are followed up. The payee may have lost it."],
  ["mc","For good control, who should reconcile the bank account?",["Someone other than the person who writes and signs the checks","The same person who signs the checks","The bank teller","Nobody: the software does it"],"Separating the two jobs makes it much harder to hide a missing payment."]]},

{id:"adj",ic:"📆",t:"Adjusting entries and the month-end close",goal:"Put income and expenses in the month they belong to, then close.",
 slides:[
  {h:"Cash basis and accrual basis",v:{k:"cmp",a:["Cash basis",["Income when money is received","Expense when money is paid","Simple; common for small service businesses"]],b:["Accrual basis",["Income when it is earned","Expense when it is used","Shows what is owed to and by the business"]]},
   ex:"A $900 job is finished Dec 20 and paid Jan 5. Accrual: December income. Cash: January income."},
  {h:"Why adjust at month end",b:["Daily entries follow the documents. Some things have no document: a month of insurance used, a month of kiln wear, three days of wages not yet paid.","Adjusting entries put those into the right month.","Each one touches an income statement account and a balance sheet account. None of them touches cash."]},
  {h:"The four you will make most",v:{k:"tiers",r:[["Prepaid used up","Debit expense, credit prepaid asset",40],["Expense owed, not yet paid","Debit expense, credit a payable",60],["Depreciation","Debit depreciation expense, credit accumulated depreciation",80],["Unearned revenue now earned","Debit unearned revenue, credit revenue",100]]},
   ex:"A fifth one: work done but not yet invoiced. Debit Accounts receivable, credit revenue."},
  {h:"The month-end checklist",v:{k:"flow",r:["Enter every sale, bill, payment and card charge","Reconcile the bank and each credit card","Review open invoices and unpaid bills","Post adjusting entries","Read the profit and loss and the balance sheet for anything odd","Close (lock) the month so nothing changes by accident"]}},
  {h:"Closing the year",b:["At year end, revenue and expense accounts are reset to zero.","The year's profit or loss moves into equity.","Owner draws are closed into equity as well.","Software does this automatically. You make sure the year is complete before it does."]}],
 ex:[
  ["je","Dec 31. The $1,200 insurance policy covers 12 months starting Dec 1. Record December's share.",null,[["D","Insurance expense","100.00"],["C","Prepaid insurance","100.00"]],["Checking","Accounts payable","Rent expense"],"1,200 ÷ 12 = 100 used this month. The prepaid asset falls to $1,100. No cash moves."],
  ["je","Dec 31. The helper worked Dec 29 to 31 and earned $300, which will be paid on the January payday.",null,[["D","Wages expense","300.00"],["C","Wages payable","300.00"]],["Checking","Payroll tax expense","Owner's draw"],"The work was done in December, so the expense belongs to December even though the check comes later."],
  ["je","Dec 31. The $900 pottery wheel is depreciated over 36 months. Record one month.",null,[["D","Depreciation expense","25.00"],["C","Accumulated depreciation","25.00"]],["Equipment","Checking","Supplies expense"],"900 ÷ 36 = 25 a month."],
  ["je","Dec 31. Of the $900 customers paid ahead, $300 of classes have now been taught.",null,[["D","Unearned revenue","300.00"],["C","Class revenue","300.00"]],["Checking","Accounts receivable","Product sales"],"That part has been earned, so it moves from the liability to revenue."],
  ["je","Dec 31. A $450 workshop was taught on Dec 30. The invoice will not go out until January.",null,[["D","Accounts receivable","450.00"],["C","Class revenue","450.00"]],["Unearned revenue","Checking","Accounts payable"],"Earned in December, so it is December revenue on accrual books, invoice or no invoice."],
  ["mc","A $900 job is finished Dec 20 and paid Jan 5. On the CASH basis, how much is December income?",["$0","$900","$450","$300"],"Cash basis counts income when the money arrives, which is January."],
  ["mc","A $900 job is finished Dec 20 and paid Jan 5. On the ACCRUAL basis, how much is December income?",["$900","$0","$450","$300"],"Accrual counts it when it is earned, which is December."],
  ["mc","The bookkeeper skips the depreciation entry all year. What is the result?",["Profit and assets are both too high","Profit is too low","Cash is too high","Liabilities are too high"],"No expense was recorded, so profit is overstated, and the equipment still shows at full cost."],
  ["mc","Which comes first at month end?",["Entering all transactions and reconciling the bank","Locking the period","Posting depreciation","Printing the statements for the owner"],"Adjust and report only after the daily records are complete and tied to the bank."],
  ["mc","December's $140 power bill arrives on Jan 8, before December is closed. On accrual books you",["record it in December: debit Utilities expense, credit Accounts payable","record it in January when it is paid","record it as a draw","leave it out because it arrived late"],"The power was used in December."],
  ["mc","After the year is closed, which accounts begin the new year at zero?",["Revenue, expenses and owner draws","Checking and Accounts receivable","Loan payable","All accounts"],"Only the accounts that measure one year are reset. Balance sheet accounts carry on."]]},

{id:"stmt",ic:"📊",t:"Reading the statements",goal:"Build and read a profit and loss and a balance sheet.",
 slides:[
  {h:"The income statement (profit and loss)",b:["It covers a period of time: a month, a quarter, a year.","Top to bottom: revenue, cost of goods sold, gross profit, operating expenses, net income."],
   v:{k:"calc",r:[["Revenue","$5,000"],["Cost of goods sold","− $1,500"],["Gross profit","$3,500",1],["Operating expenses","− $2,300"],["Net income","$1,200",1]]}},
  {h:"The balance sheet",b:["It is a snapshot of one day, usually the last day of the period.","Assets on one side; liabilities and equity on the other. The two totals are equal."],
   v:{k:"calc",r:[["Assets","$18,400",1],["Liabilities","$6,900"],["Equity","$11,500"],["Liabilities + equity","$18,400",1]]}},
  {h:"How the two connect",v:{k:"flow",r:["The income statement ends in net income","Net income is added to equity on the balance sheet","Owner draws are subtracted from equity","So the balance sheet only balances when the income statement is right"]}},
  {h:"Profit is not cash",b:["A business can show a profit and still have less cash.","Cash went out for things that are not expenses: equipment, loan principal, owner draws, inventory.","Or income was earned but customers have not paid yet.","The cash flow statement lists these differences. The owner asking 'where did the money go?' needs this explanation."]},
  {h:"Three quick readings",v:{k:"tiers",r:[["Gross margin","Gross profit ÷ revenue",50],["Net profit margin","Net income ÷ revenue",70],["Current ratio","Current assets ÷ current liabilities",100]]},
   ex:"A current ratio under 1 means the bills due soon are larger than the cash and near-cash on hand."},
  {h:"The trial balance",b:["A trial balance lists every account with its balance in a debit or credit column.","Total debits must equal total credits.","It catches one-sided and wrong-side entries. It does not catch an entry in the wrong account or an entry that is missing."]}],
 ex:[
  ["mc","Where does Rent expense appear?",["Income statement","Balance sheet"],"Expenses are on the income statement."],
  ["mc","Where does Accounts receivable appear?",["Balance sheet","Income statement"],"It is an asset."],
  ["mc","Where does Unearned revenue appear?",["Balance sheet","Income statement"],"Despite the word 'revenue', it is a liability until the work is done."],
  ["mc","Where does Product sales appear?",["Income statement","Balance sheet"],"Revenue is on the income statement."],
  ["mc","Where does Owner's draw appear?",["Balance sheet","Income statement"],"It reduces equity. It is not an expense."],
  ["mc","Where does Cost of goods sold appear?",["Income statement","Balance sheet"],"It is subtracted from revenue to get gross profit."],
  ["mc","Where does Accumulated depreciation appear?",["Balance sheet","Income statement"],"It sits under equipment and reduces it. Depreciation expense is the income statement account."],
  ["mc","Revenue $5,000 and cost of goods sold $1,500. What is gross profit?",["$3,500","$6,500","$1,200","$2,700"],"5,000 − 1,500."],
  ["mc","Gross profit $3,500 and operating expenses $2,300. What is net income?",["$1,200","$5,800","$3,500","$2,300"],"3,500 − 2,300."],
  ["mc","Net income $1,200 on revenue of $5,000. What is the net profit margin?",["24%","30%","76%","4.2%"],"1,200 ÷ 5,000 = 0.24."],
  ["mc","Assets are $18,400 and liabilities are $6,900. What is equity?",["$11,500","$25,300","$18,400","$6,900"],"Assets − liabilities."],
  ["mc","The month shows a $1,200 profit, yet the bank balance fell. Which explanation fits?",["The business bought equipment and paid down a loan, and neither is an expense","Profit and cash always match, so an entry must be missing","Depreciation used up the cash","Revenue was recorded twice"],"Cash can leave for assets, debt and draws without touching profit."],
  ["mc","Current assets are $9,000 and current liabilities are $4,500. What is the current ratio?",["2.0","0.5","4,500","13,500"],"9,000 ÷ 4,500. The business has $2 of near-cash for every $1 due soon."],
  ["tap","This trial balance is out by $1,000. One account is in the wrong column. Tap it.",[["Checking","5,000",""],["Accounts receivable","600",""],["Accounts payable","500",""],["Owner's capital","","4,000"],["Class revenue","","2,400"],["Rent expense","1,300",""]],2,"Accounts payable is a liability and belongs in the credit column. The difference (1,000) is twice the misplaced amount (500), which is the usual sign of a wrong-side entry."],
  ["mc","The trial balance totals agree. Does that prove the books are right?",["No: an entry in the wrong account or a missing entry still balances","Yes: equal totals mean no errors","Yes, if the bank is also reconciled","Only at year end"],"Equal totals prove debits equal credits, nothing more."]]}
];
